1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	type Item = { type: string };
6	
7	type Step = { op: string; items: Item[] };
8	
9	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
10	
11	const PROCESSING_FEE = 5;
12	
13	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
14	
15	const ITEM_BASE_PREMIUM: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	};
21	
22	const policyBasePremium = (items: Item[]): number =>
23	  items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
24	
25	const quote = (step: Step): QuoteResult => {
26	  const basePremium = policyBasePremium(step.items);
27	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
28	  return {
29	    premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
30	  };
31	};
32	
33	export const runScenario = (scenario: Scenario): ScenarioResults => {
34	  return { results: scenario.steps.map(quote) };
35	};
